{"file_path":"src/policies.js","content":"/**
 * The two limiter policies. Each keeps one independent state per key, and all
 * arithmetic is exact: token counts are held as integer multiples of 1/per so
 * that partial refill periods accumulate without ever being rounded away.
 */

export class TokenBucket {
  /**
   * @param {string} name
   * @param {bigint} capacity at least 1
   * @param {bigint} refill at least 0
   * @param {bigint} per at least 1
   */
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    // A full bucket, scaled by `per`.
    this.full = capacity * per
    /** @type {Map<string, { tokens: bigint, last: bigint }>} */
    this.states = new Map()
  }

  stateOf(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      // A key reaching the bucket for the first time finds it full.
      state = { tokens: this.full, last: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.stateOf(key)
    if (state.last !== null) {
      const elapsed = tick - state.last
      if (elapsed > 0n) {
        const grown = state.tokens + this.refill * elapsed
        state.tokens = grown > this.full ? this.full : grown
      }
    }
    state.last = tick
  }

  allows(key) {
    // At least one whole token, i.e. at least `per` scaled units.
    return this.stateOf(key).tokens >= this.per
  }

  record(key) {
    const state = this.stateOf(key)
    state.tokens -= this.per
  }
}

export class SlidingWindow {
  /**
   * @param {string} name
   * @param {bigint} limit at least 0
   * @param {bigint} span at least 1
   */
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    /** @type {Map<string, { ticks: bigint[], head: number }>} */
    this.states = new Map()
  }

  stateOf(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [], head: 0 }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.stateOf(key)
    const cutoff = tick - this.span
    // Recorded ticks never go backwards, so the remembered ticks are sorted
    // and the expired ones are exactly the leading run.
    while (state.head < state.ticks.length && state.ticks[state.head] <= cutoff) {
      state.head += 1
    }
    if (state.head > 32 && state.head * 2 >= state.ticks.length) {
      state.ticks = state.ticks.slice(state.head)
      state.head = 0
    }
  }

  allows(key) {
    const state = this.stateOf(key)
    return BigInt(state.ticks.length - state.head) < this.limit
  }

  record(key, tick) {
    this.stateOf(key).ticks.push(tick)
  }
}
"}

