{"file_path":"src/limiter.js","content":"/**
 * Reading a limiter file and replaying its events through the policies its
 * routes name.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

// A name, a route prefix and an event key are each one or more of these.
const TOKEN = /^[A-Za-z0-9_./:-]+$/

/** A parse failure carrying the line it was found on. */
export class LimiterError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

/**
 * An unsigned decimal integer written without a sign and without a leading
 * zero unless it is exactly `0`, and at least `least`.
 *
 * @returns {bigint|null} null when the word is not such an integer
 */
function parseCount(word, least) {
  if (!/^(0|[1-9][0-9]*)$/.test(word)) return null
  const value = BigInt(word)
  return value < least ? null : value
}

export class Limiter {
  constructor() {
    /** @type {Map<string, TokenBucket|SlidingWindow>} */
    this.policies = new Map()
    /** @type {Map<string, string[]>} */
    this.routes = new Map()
    /** @type {{ tick: bigint, key: string }[]} */
    this.events = []
    this.sawEvent = false
    /** @type {bigint|null} */
    this.lastTick = null
    /** @type {Map<string, (TokenBucket|SlidingWindow)[]>} */
    this.routeCache = new Map()
  }

  bucket(words, line) {
    if (words.length !== 5) {
      throw new LimiterError(line, 'expected bucket <name> <capacity> <refill> <per>')
    }
    const name = words[1]
    if (!TOKEN.test(name)) {
      throw new LimiterError(line, `invalid policy name ${name}`)
    }
    const capacity = parseCount(words[2], 1n)
    if (capacity === null) {
      throw new LimiterError(line, 'capacity must be an integer of at least 1')
    }
    const refill = parseCount(words[3], 0n)
    if (refill === null) {
      throw new LimiterError(line, 'refill must be an integer of at least 0')
    }
    const per = parseCount(words[4], 1n)
    if (per === null) {
      throw new LimiterError(line, 'per must be an integer of at least 1')
    }
    if (this.policies.has(name)) {
      throw new LimiterError(line, `policy ${name} is declared twice`)
    }
    this.policies.set(name, new TokenBucket(name, capacity, refill, per))
  }

  window(words, line) {
    if (words.length !== 4) {
      throw new LimiterError(line, 'expected window <name> <limit> <span>')
    }
    const name = words[1]
    if (!TOKEN.test(name)) {
      throw new LimiterError(line, `invalid policy name ${name}`)
    }
    const limit = parseCount(words[2], 0n)
    if (limit === null) {
      throw new LimiterError(line, 'limit must be an integer of at least 0')
    }
    const span = parseCount(words[3], 1n)
    if (span === null) {
      throw new LimiterError(line, 'span must be an integer of at least 1')
    }
    if (this.policies.has(name)) {
      throw new LimiterError(line, `policy ${name} is declared twice`)
    }
    this.policies.set(name, new SlidingWindow(name, limit, span))
  }

  route(words, line) {
    if (words.length < 3) {
      throw new LimiterError(line, 'expected route <prefix> <policy>...')
    }
    const prefix = words[1]
    if (!TOKEN.test(prefix)) {
      throw new LimiterError(line, `invalid route prefix ${prefix}`)
    }
    if (this.routes.has(prefix)) {
      throw new LimiterError(line, `prefix ${prefix} is routed twice`)
    }
    const named = words.slice(2)
    for (const policy of named) {
      if (!this.policies.has(policy)) {
        throw new LimiterError(line, `unknown policy ${policy}`)
      }
    }
    this.routes.set(prefix, named)
  }

  event(words, line) {
    if (words.length !== 3) {
      throw new LimiterError(line, 'expected event <tick> <key>')
    }
    const tick = parseCount(words[1], 0n)
    if (tick === null) {
      throw new LimiterError(line, 'tick must be an integer of at least 0')
    }
    const key = words[2]
    if (!TOKEN.test(key)) {
      throw new LimiterError(line, `invalid key ${key}`)
    }
    if (this.lastTick !== null && tick < this.lastTick) {
      throw new LimiterError(line, `tick ${tick} is before tick ${this.lastTick}`)
    }
    this.lastTick = tick
    this.sawEvent = true
    this.events.push({ tick, key })
  }

  /** Reads the whole file, throwing a LimiterError at the first failure. */
  read(text) {
    const lines = text.split('\n')
    // A trailing newline leaves an empty tail that is not a line.
    if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim()
      if (line === '' || line.startsWith('#')) continue
      const words = line.split(/\s+/)
      const directive = words[0]
      if (directive === 'bucket' || directive === 'window' || directive === 'route') {
        if (this.sawEvent) {
          throw new LimiterError(i + 1, 'declarations must come before the first event')
        }
      }
      switch (directive) {
        case 'bucket':
          this.bucket(words, i + 1)
          break
        case 'window':
          this.window(words, i + 1)
          break
        case 'route':
          this.route(words, i + 1)
          break
        case 'event':
          this.event(words, i + 1)
          break
        default:
          throw new LimiterError(i + 1, `unknown directive ${directive}`)
      }
    }
  }

  /**
   * The policies of the longest route prefix the key starts with, or an empty
   * list when no route matches it.
   */
  routeFor(key) {
    const cached = this.routeCache.get(key)
    if (cached !== undefined) return cached
    let best = null
    for (const prefix of this.routes.keys()) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) {
        best = prefix
      }
    }
    const chain =
      best === null ? [] : this.routes.get(best).map((name) => this.policies.get(name))
    this.routeCache.set(key, chain)
    return chain
  }

  /**
   * Every event in log order, each as { tick, key, denier }, where denier is
   * null when the event was allowed and otherwise the policy that refused it.
   */
  replay() {
    const verdicts = []
    for (const { tick, key } of this.events) {
      const chain = this.routeFor(key)
      for (const policy of chain) policy.advance(key, tick)
      let denier = null
      for (const policy of chain) {
        if (!policy.allows(key)) {
          denier = policy
          break
        }
      }
      if (denier === null) {
        for (const policy of chain) policy.record(key, tick)
      }
      verdicts.push({ tick, key, denier })
    }
    return verdicts
  }
}
"}

