import { readFileSync } from 'fs'

// Valid characters for names, prefixes, and keys
const VALID_CHARS = /^[A-Za-z0-9_.\/:/-]+$/

// Policy class hierarchy
class Policy {
  constructor(name) {
    this.name = name
  }

  allow(key, tick) {
    throw new Error('Not implemented')
  }

  record(key, tick) {
    throw new Error('Not implemented')
  }

  advance(key, tick) {
    throw new Error('Not implemented')
  }
}

class TokenBucket extends Policy {
  constructor(name, capacity, refill, per) {
    super(name)
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.states = new Map() // key -> { tokens: number, lastTick: number }
  }

  getState(key) {
    if (!this.states.has(key)) {
      this.states.set(key, { tokens: this.capacity, lastTick: null })
    }
    return this.states.get(key)
  }

  advance(key, tick) {
    const state = this.getState(key)
    if (state.lastTick !== null && tick > state.lastTick) {
      const ticksPassed = tick - state.lastTick
      const tokensToAdd = (this.refill * ticksPassed) / this.per
      state.tokens = Math.min(this.capacity, state.tokens + tokensToAdd)
    }
    state.lastTick = tick
  }

  allow(key, tick) {
    const state = this.getState(key)
    return state.tokens >= 1
  }

  record(key, tick) {
    const state = this.getState(key)
    state.tokens -= 1
  }
}

class SlidingWindow extends Policy {
  constructor(name, limit, span) {
    super(name)
    this.limit = limit
    this.span = span
    this.states = new Map() // key -> { ticks: number[] }
  }

  getState(key) {
    if (!this.states.has(key)) {
      this.states.set(key, { ticks: [] })
    }
    return this.states.get(key)
  }

  advance(key, tick) {
    const state = this.getState(key)
    const cutoff = tick - this.span
    // Remove ticks at or before cutoff
    state.ticks = state.ticks.filter(t => t > cutoff)
  }

  allow(key, tick) {
    const state = this.getState(key)
    return state.ticks.length < this.limit
  }

  record(key, tick) {
    const state = this.getState(key)
    state.ticks.push(tick)
  }
}

// Main parser and executor
class LimiterSimulator {
  constructor() {
    this.policies = new Map() // name -> Policy
    this.routes = new Map() // prefix -> policy names[]
    this.events = [] // { tick, key }
    this.firstEventLineNumber = null
    this.lastTick = null
  }

  validateName(name) {
    return VALID_CHARS.test(name)
  }

  validateInteger(value, min) {
    if (!Number.isInteger(value) || value < min) {
      return false
    }
    // Check for leading zeros (except "0" itself)
    if (value !== 0 && value.toString().startsWith('0')) {
      return false
    }
    return true
  }

  parseInteger(str, min) {
    if (!/^\d+$/.test(str)) {
      return null
    }
    // Check for leading zeros
    if (str !== '0' && str.startsWith('0')) {
      return null
    }
    const value = parseInt(str, 10)
    if (value < min) {
      return null
    }
    return value
  }

  parseBucket(parts, lineNumber) {
    if (parts.length !== 5) {
      return { error: 'expected bucket <name> <capacity> <refill> <per>' }
    }

    const name = parts[1]
    if (!this.validateName(name)) {
      return { error: `invalid policy name ${name}` }
    }

    const capacity = this.parseInteger(parts[2], 1)
    if (capacity === null) {
      return { error: 'capacity must be an integer of at least 1' }
    }

    const refill = this.parseInteger(parts[3], 0)
    if (refill === null) {
      return { error: 'refill must be an integer of at least 0' }
    }

    const per = this.parseInteger(parts[4], 1)
    if (per === null) {
      return { error: 'per must be an integer of at least 1' }
    }

    if (this.policies.has(name)) {
      return { error: `policy ${name} is declared twice` }
    }

    this.policies.set(name, new TokenBucket(name, capacity, refill, per))
    return { success: true }
  }

  parseWindow(parts, lineNumber) {
    if (parts.length !== 4) {
      return { error: 'expected window <name> <limit> <span>' }
    }

    const name = parts[1]
    if (!this.validateName(name)) {
      return { error: `invalid policy name ${name}` }
    }

    const limit = this.parseInteger(parts[2], 0)
    if (limit === null) {
      return { error: 'limit must be an integer of at least 0' }
    }

    const span = this.parseInteger(parts[3], 1)
    if (span === null) {
      return { error: 'span must be an integer of at least 1' }
    }

    if (this.policies.has(name)) {
      return { error: `policy ${name} is declared twice` }
    }

    this.policies.set(name, new SlidingWindow(name, limit, span))
    return { success: true }
  }

  parseRoute(parts, lineNumber) {
    if (parts.length < 3) {
      return { error: 'expected route <prefix> <policy>...' }
    }

    const prefix = parts[1]
    if (!this.validateName(prefix)) {
      return { error: `invalid route prefix ${prefix}` }
    }

    if (this.routes.has(prefix)) {
      return { error: `prefix ${prefix} is routed twice` }
    }

    const policyNames = parts.slice(2)
    for (const policyName of policyNames) {
      if (!this.policies.has(policyName)) {
        return { error: `unknown policy ${policyName}` }
      }
    }

    this.routes.set(prefix, policyNames)
    return { success: true }
  }

  parseEvent(parts, lineNumber) {
    if (parts.length !== 3) {
      return { error: 'expected event <tick> <key>' }
    }

    if (this.firstEventLineNumber === null) {
      this.firstEventLineNumber = lineNumber
    }

    const tick = this.parseInteger(parts[1], 0)
    if (tick === null) {
      return { error: 'tick must be an integer of at least 0' }
    }

    if (this.lastTick !== null && tick < this.lastTick) {
      return { error: `tick ${tick} is before tick ${this.lastTick}` }
    }
    this.lastTick = tick

    const key = parts[2]
    if (!this.validateName(key)) {
      return { error: `invalid key ${key}` }
    }

    this.events.push({ tick, key })
    return { success: true }
  }

  parseLine(line, lineNumber) {
    // Trim and ignore empty lines
    line = line.trim()
    if (!line || line.startsWith('#')) {
      return { success: true }
    }

    // Split on runs of whitespace
    const parts = line.split(/\s+/)
    const directive = parts[0]

    // Check if we're trying to declare after first event
    if (this.firstEventLineNumber !== null) {
      if (directive === 'bucket' || directive === 'window' || directive === 'route') {
        return { error: 'declarations must come before the first event' }
      }
    }

    switch (directive) {
      case 'bucket':
        return this.parseBucket(parts, lineNumber)
      case 'window':
        return this.parseWindow(parts, lineNumber)
      case 'route':
        return this.parseRoute(parts, lineNumber)
      case 'event':
        return this.parseEvent(parts, lineNumber)
      default:
        return { error: `unknown directive ${directive}` }
    }
  }

  parse(input) {
    const lines = input.split('\n')
    // Drop empty tail from trailing newline
    if (lines.length > 0 && lines[lines.length - 1] === '') {
      lines.pop()
    }

    for (let i = 0; i < lines.length; i++) {
      const result = this.parseLine(lines[i], i + 1)
      if (!result.success) {
        return { error: result.error, lineNumber: i + 1 }
      }
    }

    return { success: true }
  }

  findRoute(key) {
    let bestPrefix = null
    let bestLength = -1

    for (const prefix of this.routes.keys()) {
      if (key.startsWith(prefix) && prefix.length > bestLength) {
        bestPrefix = prefix
        bestLength = prefix.length
      }
    }

    return bestPrefix ? this.routes.get(bestPrefix) : null
  }

  simulate() {
    const results = []

    for (const event of this.events) {
      const { tick, key } = event
      const route = this.findRoute(key)

      if (!route) {
        // No route matches, always allow
        results.push({ tick, key, allowed: true })
        continue
      }

      // Advance all policies
      for (const policyName of route) {
        const policy = this.policies.get(policyName)
        policy.advance(key, tick)
      }

      // Check all policies
      let allowed = true
      let deniedBy = null

      for (const policyName of route) {
        const policy = this.policies.get(policyName)
        if (!policy.allow(key, tick)) {
          allowed = false
          deniedBy = policyName
          break
        }
      }

      // Record if allowed
      if (allowed) {
        for (const policyName of route) {
          const policy = this.policies.get(policyName)
          policy.record(key, tick)
        }
      }

      results.push({ tick, key, allowed, deniedBy })
    }

    return results
  }
}

function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read all input from stdin
  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch (e) {
    // If reading fails, treat as empty input
    input = ''
  }

  const simulator = new LimiterSimulator()
  const parseResult = simulator.parse(input)

  if (!parseResult.success) {
    process.stderr.write(
      `error: line ${parseResult.lineNumber}: ${parseResult.error}\n`
    )
    process.exit(2)
  }

  const results = simulator.simulate()

  if (mode === 'replay') {
    for (const result of results) {
      if (result.allowed) {
        process.stdout.write(`${result.tick} ${result.key} allow\n`)
      } else {
        process.stdout.write(`${result.tick} ${result.key} deny ${result.deniedBy}\n`)
      }
    }
  } else if (mode === 'summary') {
    const keyStats = new Map() // key -> { allowed: number, denied: number }

    for (const result of results) {
      if (!keyStats.has(result.key)) {
        keyStats.set(result.key, { allowed: 0, denied: 0 })
      }
      const stats = keyStats.get(result.key)
      if (result.allowed) {
        stats.allowed++
      } else {
        stats.denied++
      }
    }

    // Output in ascending key order
    const sortedKeys = Array.from(keyStats.keys()).sort()
    for (const key of sortedKeys) {
      const stats = keyStats.get(key)
      process.stdout.write(`${key} allowed=${stats.allowed} denied=${stats.denied}\n`)
    }

    // Calculate totals
    let totalAllowed = 0
    let totalDenied = 0
    for (const stats of keyStats.values()) {
      totalAllowed += stats.allowed
      totalDenied += stats.denied
    }

    process.stdout.write(`total allowed=${totalAllowed} denied=${totalDenied}\n`)
  }

  process.exit(0)
}

main()

