import { readFileSync, writeSync } from 'node:fs'
import { Limiter, LimiterError } from './limiter.js'

/** Writes the whole text to a descriptor, however it has to be split up. */
function writeAll(fd, text) {
  if (text === '') return
  const buffer = Buffer.from(text, 'utf8')
  let written = 0
  while (written < buffer.length) {
    try {
      written += writeSync(fd, buffer, written, buffer.length - written)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EPIPE') return
      throw error
    }
  }
}

function fail(message) {
  writeAll(2, `error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    fail('usage: cli.js replay|summary')
  }
  const mode = args[0]

  let text = ''
  try {
    text = readFileSync(0, 'utf8')
  } catch {
    text = ''
  }

  const limiter = new Limiter()
  try {
    limiter.read(text)
  } catch (error) {
    if (error instanceof LimiterError) fail(error.message)
    throw error
  }

  const verdicts = limiter.replay()
  const out = []

  if (mode === 'replay') {
    for (const { tick, key, denier } of verdicts) {
      out.push(denier === null ? `${tick} ${key} allow\n` : `${tick} ${key} deny ${denier.name}\n`)
    }
  } else {
    const counts = new Map()
    let allowed = 0
    let denied = 0
    for (const verdict of verdicts) {
      let count = counts.get(verdict.key)
      if (count === undefined) {
        count = { allowed: 0, denied: 0 }
        counts.set(verdict.key, count)
      }
      if (verdict.denier === null) {
        count.allowed += 1
        allowed += 1
      } else {
        count.denied += 1
        denied += 1
      }
    }
    for (const key of [...counts.keys()].sort()) {
      const count = counts.get(key)
      out.push(`${key} allowed=${count.allowed} denied=${count.denied}\n`)
    }
    out.push(`total allowed=${allowed} denied=${denied}\n`)
  }

  writeAll(1, out.join(''))
}

main()

